  ('9b246f64-8b9e-5089-a86e-1e232cab677f', '22222222-2222-2222-2222-222222222217', 'mcq', '如图，在长方形𝐴𝐸𝐶𝐷中，𝐴𝐷= 10，𝐶𝐷= 12，𝐵在𝐴𝐸的延长线上， 𝐵𝐷交𝐶𝐸于𝐹，△𝐶𝐹𝐵的面积为24，则△𝐹𝐸𝐵的面积等于( ).', '[{"key": "A", "text": "16"}, {"key": "B", "text": "15"}, {"key": "C", "text": "14"}, {"key": "D", "text": "13"}, {"key": "E", "text": "12"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 27, true, 216, null),
  ('9425e00c-e121-5a71-aab5-c29833e5603c', '22222222-2222-2222-2222-222222222217', 'mcq', '如图，先将矩形纸片𝐴𝐵𝐶𝐷对折一次折痕为𝐸𝐹，展开后又将纸片折叠 使点𝐴落在𝐸𝐹上，此时折痕为𝐵𝑀，求∠𝑁𝐵𝐶度数的大小( ).', '[{"key": "A", "text": "20°"}, {"key": "B", "text": "25°"}, {"key": "C", "text": "30°"}, {"key": "D", "text": "35°"}, {"key": "E", "text": "45°"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 28, true, 217, null),
  ('206853d3-9acd-5c83-99db-1c3d720d5d2f', '22222222-2222-2222-2222-222222222218', 'short', '利用夹角求面积：𝑆= 1 2 𝑎𝑏sin𝐶.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 1, null),
  ('8a92175e-be52-5999-9c0d-78f45781bdf0', '22222222-2222-2222-2222-222222222218', 'short', '利用边长求面积：𝑆= √𝑝(𝑝−𝑎)(𝑝−𝑏)(𝑝−𝑐)，其中𝑝= 1 2(𝑎+ 𝑏+ 𝑐).', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 2, null),
  ('8c381f08-fbce-50fc-a37b-f4b50ad126f7', '22222222-2222-2222-2222-222222222218', 'short', '蝴蝶定理： 𝑆1 𝑆2 = ( 𝑎 𝑏) 2 ；𝑆3 = 𝑆4 ； 𝑆1 𝑆3 = 𝑆4 𝑆2 ⇔ 𝑆1 ⋅𝑆2 = 𝑆3 ⋅𝑆4.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 3, null),
  ('dd550354-9bcf-5760-ba4e-dd046955cd36', '22222222-2222-2222-2222-222222222218', 'short', '圆的半径为𝑟，周长：𝐶= 2π𝑟；面积：𝑆= π𝑟2.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 4, null),
  ('d176bc45-652e-5a6e-a7ee-923ea626696c', '22222222-2222-2222-2222-222222222218', 'short', '扇形弧长：𝑙= 𝛼° 360° × 2π𝑟= π𝑟𝛼° 180°. 扇形面积：𝑆扇形= 𝛼° 360° × π𝑟2 = 1 2 𝑙𝑟.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 5, null),
  ('70583ff0-ef94-53ea-83ad-647542f90993', '22222222-2222-2222-2222-222222222218', 'short', '三角形内心，是内切圆圆心，也是三条角平分线的交点，三角形面积𝑆= 1 2(𝑎+ 𝑏+ 𝑐) ⋅𝑟，直角三角形中，内切圆半径𝑟= 𝑎+𝑏−𝑐 2 ，即两直角边之和减 去斜边的差除以2.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 6, null),
  ('246b5d8b-07b9-51cb-8702-1c7e831c171e', '22222222-2222-2222-2222-222222222218', 'short', '三角形外心，是外接圆圆心,也是三条边垂直平分线（中垂线）的交点.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 7, null),
  ('e4a48f21-f185-599d-a443-510207f5dc6a', '22222222-2222-2222-2222-222222222218', 'short', '如果一个四边形的对角线互相垂直，那么这个四边形就是垂美四边形.则 𝑆𝐴𝐵𝐶𝐷= 1 2𝐴𝐶⋅𝐵𝐷. 𝐴𝐶和𝐵𝐷是互相垂直的对角线. 知新 主讲人：十一老师 现在是网络设备测试时间，课程将准时开始，请大家耐心等待 你的坚持，终将美好！ 第八章 解析几何 考点1 平面直角坐标系 考点2 直线 考点3 圆 考点4 位置关系 考点5 对称关系 考点6 最值与不等式 你的坚持，终将美好！ 1 考点1：平面直角坐标系', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 8, null),
  ('4409894c-0f58-5266-85f5-8bc0da46eb8d', '22222222-2222-2222-2222-222222222218', 'short', '平面直角坐标系的定义：在同一个平面上互相垂直且有公共原点的两条 数轴构成平面直角坐标系，简称直角坐标系.通常，两条数轴分别置于水 平位置与垂直位置，取向右与向上的方向分别为两条数轴的正方向.水平 的数轴叫作𝑥轴或横轴，垂直的数轴叫作𝑦轴或纵轴，𝑥轴、𝑦轴统称为坐 标轴，它们的公共点𝑂称为直角坐标系的原点，以点𝑂为原点的平面直角 坐标系记作平面直角坐标系𝑥𝑂𝑦.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 9, null),
  ('34851aaf-de91-5af4-954c-328c97bf643c', '22222222-2222-2222-2222-222222222218', 'short', '象限：如图（𝑎），以原点为中心，𝑥轴、𝑦轴为分界线.右上的称为第一象 限，左上的称为第二象限，左下的称为第三象限，右下的称为第四象限. 原点和坐标轴上的点不属于任何象限. （𝑎） （𝑏）', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 10, null),
  ('1948d4d3-66d8-5eb8-878a-ee51a2e8ad7d', '22222222-2222-2222-2222-222222222218', 'short', '点的表示：如图（𝑏），过点𝑃分别向𝑥轴和𝑦轴作垂线，垂足𝐴在𝑥轴上的 坐标是𝑥，垂足𝐵在𝑦轴上的坐标是𝑦，我们说点𝑃的横坐标是𝑥，纵坐标是 𝑦，有序数对(𝑥, 𝑦)叫作点𝑃的坐标，即𝑃(𝑥, 𝑦). 你的坚持，终将美好！ 2', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 11, null),
  ('f6ecf7e7-38cc-51e3-8004-c942a3e3fe92', '22222222-2222-2222-2222-222222222218', 'short', '两点的中点坐标：𝑃1(𝑥1,𝑦1)与𝑃2(𝑥2,𝑦2)的中点坐标为( 𝑥1+𝑥2 2 , 𝑦1+𝑦2 2 )， 特别地，𝑃(𝑥, 𝑦)与原点的中点坐标为( 𝑥 2 , 𝑦', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 12, null),
  ('901b38da-d7bb-5751-a25e-4650a3ae06eb', '22222222-2222-2222-2222-222222222218', 'short', '. 题型1：考查两点的中点坐标', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 13, null),
  ('73aff811-dadb-55d7-82ac-ed9a36c625a9', '22222222-2222-2222-2222-222222222218', 'mcq', '已知点𝐴的坐标为(𝑚, 4)，点𝐵的坐标为(3, 𝑛)，𝐶(1,3)为线段𝐴𝐵上的 中点，则( ).', '[{"key": "A", "text": "𝑚= 1, 𝑛= 2"}, {"key": "B", "text": "𝑚= −1, 𝑛= −2"}, {"key": "C", "text": "𝑚= −1, 𝑛= 2"}, {"key": "D", "text": "𝑚= 0,𝑛= 2"}, {"key": "E", "text": "𝑚= −1, 𝑛= 1"}]'::jsonb, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 14, null),
  ('04e2ee3d-e890-5010-8753-a8419d169951', '22222222-2222-2222-2222-222222222218', 'short', '两点距离公式：', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 15, null),
  ('5f6a7d07-5965-584a-8cf4-55fbdce0f656', '22222222-2222-2222-2222-222222222218', 'short', '点𝐴(𝑥1,𝑦1)与𝐵(𝑥2,𝑦2)之间的距离𝑑= √(𝑥2 −𝑥1)2 + (𝑦2 −𝑦1)2.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 16, null),
  ('d05efdde-c804-578f-84c1-6cce4f173eb5', '22222222-2222-2222-2222-222222222218', 'short', '点𝐴(𝑥1,𝑦1)与原点之间的距离𝑑= √𝑥1 2 + 𝑦1 2. 题型2：考查两点间的距离求解', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 17, null),
  ('5ece8089-3a8f-5556-a768-d299ded59378', '22222222-2222-2222-2222-222222222218', 'mcq', '已知𝐴(1,2)，𝐵(4,6)，则以线段𝐴𝐵为边长的等边三角形的面积为( ). A. 25 4 √3 B. 5 4 √3 C. 25 4', '[{"key": "D", "text": "25√3"}, {"key": "E", "text": "25"}]'::jsonb, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 18, null),
  ('fab713ae-6243-5393-aa52-70f7b5e5d119', '22222222-2222-2222-2222-222222222218', 'short', '倾斜角：直线与𝑥轴正方向所成的夹角，称为倾斜角，可记为𝛼. 其中 𝛼∈[0, π). 直线的倾斜角表示平面内一条直线的倾斜程度.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, true, 19, null),
  ('5ed912b5-2ba4-592d-9ae2-641d340811ad', '22222222-2222-2222-2222-222222222218', 'short', '斜率：倾斜角的正切值称为斜率，记𝑘= tan𝛼= 对边 邻边, (𝛼≠ π', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, true, 20, null),
  ('6a8bcd94-c631-530c-9440-f7b95929d9a4', '22222222-2222-2222-2222-222222222218', 'short', '. 根据图象可以发现， 当0 < 𝛼< 90°时，斜率𝑘> 0，𝛼越大，斜率𝑘的值越来越大； 当90° < 𝛼< 180°时，斜率𝑘< 0，𝛼越大，斜率𝑘的值越来越大； 角度 0° 30° 45° 60° 90° 120° 135° 150° 180° 弧度 0 π 6 π 4 π 3 π 2 2π 3 3π 4 5π 6 π tan𝜃 0 √3 3 1 √3 不存在 −√3 −1 −√3 3 0 你的坚持，终将美好！ 5', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, true, 21, null),
  ('4a167b8e-bb60-5df0-8b6d-47a45b53d1c7', '22222222-2222-2222-2222-222222222218', 'short', '两点斜率公式：设直线𝑙上有两个点𝑃1(𝑥1,𝑦1)与𝑃2(𝑥2,𝑦2)，则𝑘= 𝑦2−𝑦1 𝑥2−𝑥1， 其中𝑥1 ≠𝑥2. 题型1：考查直线斜率的计算', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 22, null),
  ('35d8fd56-c9a7-5a84-9de5-824f26d7eb95', '22222222-2222-2222-2222-222222222218', 'mcq', '已知直线𝑙过点𝑃(−1,2)，且与以𝐴(−2, −3)，𝐵(3,0)为端点的线段相 交，则直线𝑙的斜率的取值范围是( ).', '[{"key": "A", "text": "[−1 2 , 5]"}, {"key": "B", "text": "(−1 2 , 5]"}, {"key": "C", "text": "[−1 2 , +∞)"}, {"key": "D", "text": "(−∞, −"}]'::jsonb, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 23, null),
  ('0e7b426a-8e94-5630-853e-70036057c79e', '22222222-2222-2222-2222-222222222218', 'short', '点斜式：过点𝑃(𝑥0,𝑦0)，斜率为𝑘的直线方程为𝑦−𝑦0 = 𝑘(𝑥−𝑥0). （☆）', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 24, null),
  ('a7cdd6b5-d4c2-5886-814b-b7ce4cf33f1c', '22222222-2222-2222-2222-222222222218', 'short', '斜截式：斜率为𝑘，在𝑦轴上截距为𝑏（即过点𝑃0(0, 𝑏)）的直线方程为 𝑦= 𝑘𝑥+ 𝑏.（☆）', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 25, null),
  ('0cc15dda-f147-57e3-8ee6-8d4ac328f66e', '22222222-2222-2222-2222-222222222218', 'short', '两点式：过两个点𝑃1(𝑥1,𝑦1)，𝑃2(𝑥2,𝑦2)的直线方程为 𝑦−𝑦1 𝑦2−𝑦1 = 𝑥−𝑥1 𝑥2−𝑥1 ， (𝑥1 ≠𝑥2,𝑦1 ≠𝑦2).', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 26, null),
  ('3b53f2cf-28fa-5a9a-924b-42cb801ac228', '22222222-2222-2222-2222-222222222218', 'short', '截距式：在𝑥轴上的截距为𝑎（即过点𝑃1(𝑎, 0)），在𝑦轴上的截距为𝑏 （即过点𝑃0(0, 𝑏)）的直线方程为 𝑥 𝑎+ 𝑦 𝑏= 1(𝑎≠0, 𝑏≠0). 截距：截距分为横截距和纵截距，横截距是直线与𝑥轴交点的横坐标，纵 截距是直线与𝑦轴交点的纵坐标. 要求出横截距，只需令𝑦= 0，求出𝑥， 求纵截距就令𝑥= 0，求出𝑦. 如𝑦= 𝑥−1横截距为1，纵截距为−1. 【注】直线的截距可正，可负，可为0.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 27, null),
  ('5f4ea692-4d23-5833-8473-c98f05eaf2cd', '22222222-2222-2222-2222-222222222218', 'short', '一般式：𝑎𝑥+ 𝑏𝑦+ 𝑐= 0（𝑎, 𝑏不全为零）.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 28, null),
  ('08150dc8-ac00-55a8-bf66-9ed833b638a2', '22222222-2222-2222-2222-222222222218', 'short', '𝑎= 0时，为水平直线，𝑦= − 𝑐 𝑏.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 29, null),
  ('83f31693-30f3-587a-99db-c57ce47aa29a', '22222222-2222-2222-2222-222222222218', 'short', '𝑏= 0时，为竖直直线，𝑥= − 𝑐 𝑎.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 30, null),
  ('f6d3449f-ad31-58d6-a760-da8cab98acef', '22222222-2222-2222-2222-222222222218', 'short', '𝑐= 0时，直线过原点(0,0).', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 31, null),
  ('0816c937-aa97-590b-8240-0f5aeadadb64', '22222222-2222-2222-2222-222222222218', 'short', '𝑏≠0时，𝑦= − 𝑎 𝑏𝑥− 𝑐 𝑏， 此时斜率𝑘= − 𝑎 𝑏，在𝑥轴上的截距为− 𝑐 𝑎，在𝑦轴上的截距为− 𝑐 𝑏. 你的坚持，终将美好！ 7 题型2：考查截距的计算', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 32, null),
  ('05850e7b-1d68-5d8f-b1a0-9605776e3bd3', '22222222-2222-2222-2222-222222222218', 'mcq', '已知𝐴(1,−3)，B(3, −1)，直线𝐴𝐵在𝑦轴上的截距为( ).', '[{"key": "A", "text": "5"}, {"key": "B", "text": "−2"}, {"key": "C", "text": "−3"}, {"key": "D", "text": "−4"}, {"key": "E", "text": "−5 要求判断每题给出的条件（1）和（2）能否充分支持题干所陈述的结论．以下五个选项为判 断结果，请选择一项符合试题要求的判断。"}, {"key": "A", "text": "条件（1）充分，但条件（2）不充分"}, {"key": "B", "text": "条件（2）充分，但条件（1）不充分"}, {"key": "C", "text": "条件（1）和（2）单独都不充分，但条件（1）和条件（2）联合起来充分"}, {"key": "D", "text": "条件（1）充分，条件（2）也充分"}, {"key": "E", "text": "条件（1）和条件（2）单独都不充分，条件（1）和条件（2）联合起来也不充分"}]'::jsonb, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 33, null),
  ('f649ff9f-46f5-5751-b630-74a277cd4817', '22222222-2222-2222-2222-222222222218', 'short', '直线𝑦= 𝑎𝑥+ 𝑏经过第一、二、四象限.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 34, null),
  ('42be19bc-36a8-53ee-ba71-d1063ade15ff', '22222222-2222-2222-2222-222222222218', 'short', '𝑎< 0.', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 35, null),
  ('1b575546-3d91-5181-9b88-9daa9fcc0789', '22222222-2222-2222-2222-222222222218', 'short', '𝑏> 0. 你的坚持，终将美好！ 8 你的坚持，终将美好！ 9 三、距离公式', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 36, null),
  ('40fee764-bd0f-5543-8c48-43af8bae62f9', '22222222-2222-2222-2222-222222222218', 'short', '点到直线的距离：（化简成一般式再代入） 点(𝑥0,𝑦0)到直线𝑎𝑥+ 𝑏𝑦+ 𝑐= 0的距离𝑑= |𝑎𝑥0+𝑏𝑦0+𝑐| √𝑎2+𝑏2 .（☆） 特别地：原点到直线𝑎𝑥+ 𝑏𝑦+ 𝑐= 0的距离𝑑= |𝑐| √𝑎2+𝑏2. 点(𝑥0,𝑦0)到水平线𝑦= 𝑐的距离𝑑= |𝑦0 −𝑐|. 点(𝑥0,𝑦0)到竖直线𝑥= 𝑐的距离𝑑= |𝑥0 −𝑐|. 题型4：考查点到直线的距离', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 11, true, 37, null),
  ('0377a495-065d-5efe-a564-273695fee2ce', '22222222-2222-2222-2222-222222222218', 'mcq', '已知点𝑃(2, −3)到直线3𝑥−4𝑦+ 𝑐= 0的距离为 23 5 ，则𝑐为( ).', '[{"key": "A", "text": "41"}, {"key": "B", "text": "5"}, {"key": "C", "text": "5或31"}, {"key": "D", "text": "5或−41"}, {"key": "E", "text": "−5或41"}]'::jsonb, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 11, true, 38, null),
  ('853c7e29-978c-57aa-8831-0ebf18b87a64', '22222222-2222-2222-2222-222222222218', 'short', '两平行直线之间的距离： 直线𝑎𝑥+ 𝑏𝑦+ 𝑐1 = 0与直线𝑎𝑥+ 𝑏𝑦+ 𝑐2 = 0的距离𝑑= |𝑐1−𝑐2| √𝑎2+𝑏2. 题型5：考查两平行直线之间的距离', null, '', '', '数学/第8章 解析几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 39, null)
